mapper.update:
UPDATE storage_slot
SET status = 'RESERVED',
    reserved_task_id = #{reservedTaskId},
    updated_at = #{updatedAt}
WHERE id = #{slotId}
  AND status = 'EMPTY'

UPDATE storage_slot
SET status = 'OCCUPIED',
    stored_cargo_id = #{storedCargoId},
    updated_at = #{updatedAt}
WHERE id = #{slotId}
  AND status = 'RESERVED'

UPDATE storage_slot
SET stored_cargo_id = #{storedCargoId},
    updated_at = #{updatedAt}
WHERE id = #{slotId}
